@dataclass
class Task:
    """Represents a pet-care task with scheduling metadata and recurrence rules."""

    title: str
    durationMinutes: int
    priority: int
    description: str
    isCompleted: bool = False
    recurrence: str = ""
    startTime: str = "00:00"
    dueDate: Optional[datetime] = None
    appliesTo: List[Pet] = field(default_factory=list)

    def markComplete(self) -> Optional["Task"]:
        """Mark this task as completed; return the next occurrence for daily/weekly tasks."""
        self.isCompleted = True
        if not self.isRecurring():
            return None

        base = self.dueDate if self.dueDate else datetime.now()
        recurrence_lower = self.recurrence.lower()

        if "daily" in recurrence_lower:
            next_due = base + timedelta(days=1)
        elif "weekly" in recurrence_lower:
            next_due = base + timedelta(weeks=1)
        else:
            return None

        return replace(self, isCompleted=False, dueDate=next_due)

    def getPriority(self) -> int:
        """Return the numeric priority level of this task."""
        return self.priority

    def getDuration(self) -> int:
        """Return the duration of this task in minutes."""
        return self.durationMinutes

    def isRecurring(self) -> bool:
        """Return True if this task recurs on a schedule."""
        return bool(self.recurrence and self.recurrence.lower() != "once")

    def getNextOccurrence(self) -> datetime:
        """Calculate and return the next scheduled occurrence of this task."""
        now = datetime.now()

        hour, minute = (int(x) for x in self.startTime.split(":"))

        if not self.isRecurring():
            return now.replace(hour=hour, minute=minute, second=0, microsecond=0)

        recurrence_lower = self.recurrence.lower()
        if "daily" in recurrence_lower:
            next_time = now.replace(hour=hour, minute=minute, second=0, microsecond=0)
            if next_time <= now:
                next_time += timedelta(days=1)
        elif "weekly" in recurrence_lower:
            next_time = now.replace(hour=hour, minute=minute, second=0, microsecond=0)
            if next_time <= now:
                next_time += timedelta(weeks=1)
        elif "monthly" in recurrence_lower:
            next_time = now.replace(hour=hour, minute=minute, second=0, microsecond=0, day=1)
            if next_time <= now:
                if now.month == 12:
                    next_time = next_time.replace(year=now.year + 1, month=1)
                else:
                    next_time = next_time.replace(month=now.month + 1)
        else:
            next_time = now.replace(hour=hour, minute=minute, second=0, microsecond=0)

        return next_time

    def to_dict(self) -> dict:
        """Convert this task into a JSON-serializable dictionary.

        Two values can't go straight into JSON:
          - dueDate is a datetime -> store as an ISO-8601 string (or None).
          - appliesTo holds Pet objects -> store only their names, so we don't
            duplicate pet data and can reconnect to the real Pet objects on load.
        """
        return {
            "title": self.title,
            "durationMinutes": self.durationMinutes,
            "priority": self.priority,
            "description": self.description,
            "isCompleted": self.isCompleted,
            "recurrence": self.recurrence,
            "startTime": self.startTime,
            "dueDate": self.dueDate.isoformat() if self.dueDate else None,
            "appliesTo": [pet.name for pet in self.appliesTo],
        }

    @classmethod
    def from_dict(cls, data: dict, pet_lookup: Dict[str, "Pet"]) -> "Task":
        """Rebuild a Task from a dictionary produced by to_dict().

        pet_lookup maps pet name -> Pet instance, letting us re-link appliesTo
        back to the shared Pet objects (names with no matching pet are skipped).
        """
        due_raw = data.get("dueDate")
        return cls(
            title=data["title"],
            durationMinutes=data["durationMinutes"],
            priority=data["priority"],
            description=data.get("description", ""),
            isCompleted=data.get("isCompleted", False),
            recurrence=data.get("recurrence", ""),
            startTime=data.get("startTime", "00:00"),
            dueDate=datetime.fromisoformat(due_raw) if due_raw else None,
            appliesTo=[pet_lookup[name] for name in data.get("appliesTo", []) if name in pet_lookup],
        )


