@dataclass
class Scheduler:
    """Orchestrates pet-care scheduling for an owner across one or more pets."""

    owner: Owner
    pets: List[Pet] = field(default_factory=list)
    tasks: List[Task] = field(default_factory=list)
    schedule: List[ScheduledTask] = field(default_factory=list)

    def loadTasksFromOwner(self) -> List[Task]:
        """Retrieve all tasks from the owner's master task list."""
        self.tasks = self.owner.tasks
        return self.tasks

    def save_to_json(self, path: str = "data.json") -> None:
        """Persist the owner, pets, and tasks to a JSON file on disk.

        The generated schedule (self.schedule) is intentionally not saved: it is
        derived state that can be rebuilt with generateSchedule() after loading.
        """
        state = {"owner": self.owner.to_dict()}
        Path(path).write_text(json.dumps(state, indent=2), encoding="utf-8")

    @classmethod
    def load_from_json(cls, path: str = "data.json") -> "Scheduler":
        """Load a Scheduler back from a JSON file written by save_to_json().

        Returns a fresh Scheduler whose owner, pets, and tasks are reconnected to
        the same shared Pet objects. Raises FileNotFoundError if the file is
        missing, so callers can fall back to creating an empty system.
        """
        state = json.loads(Path(path).read_text(encoding="utf-8"))
        owner = Owner.from_dict(state["owner"])
        scheduler = cls(owner=owner, pets=list(owner.pets), tasks=list(owner.tasks))
        return scheduler

    def addTask(self, task: Task) -> None:
        """Add a task to the scheduler's task list."""
        self.tasks.append(task)

    def removeTask(self, taskId: str) -> None:
        """Remove a task from the scheduler's task list by its identifier."""
        self.tasks = [t for t in self.tasks if t.title != taskId]

    def sortTasks(self) -> List[Task]:
        """Return tasks sorted by priority and other scheduling criteria."""
        return sorted(
            self.tasks,
            key=lambda t: (t.getPriority(), t.startTime, -t.durationMinutes)
        )

    def sort_by_time(self) -> List[Task]:
        """Return tasks sorted by scheduled time (HH:MM string), then by priority.

        HH:MM strings are zero-padded, so lexicographic order == chronological order:
          "07:00" < "08:30" < "14:00" — no datetime parsing needed.
        """
        return sorted(self.tasks, key=lambda t: (t.startTime, t.priority))

    def filterTasks(
        self,
        completed: Optional[bool] = None,
        pet_name: Optional[str] = None,
    ) -> List[Task]:
        """Filter tasks by completion status and/or the name of the pet they apply to."""
        result = self.tasks
        if completed is not None:
            result = [t for t in result if t.isCompleted == completed]
        if pet_name is not None:
            result = [t for t in result if any(p.name == pet_name for p in t.appliesTo)]
        return result

    def filterByTimeAvailable(self) -> List[Task]:
        """Return only the tasks that fit within the owner's available hours."""
        available_minutes = self.owner.availableHours * 60
        total_duration = 0
        filtered_tasks = []

        for task in self.sortTasks():
            if total_duration + task.durationMinutes <= available_minutes:
                filtered_tasks.append(task)
                total_duration += task.durationMinutes

        return filtered_tasks

    def expandRecurringTasks(self) -> List[Task]:
        """Expand recurring tasks into individual instances for the current day."""
        expanded = []
        for task in self.tasks:
            if task.isRecurring():
                expanded.append(task)
            else:
                expanded.append(task)
        return expanded

    def handleConflicts(self) -> List[ScheduledTask]:
        """Resolve any scheduling conflicts and return a conflict-free schedule."""
        if not self.schedule:
            return []

        resolved = []
        current_hour = 0

        for scheduled in sorted(self.schedule, key=lambda s: s.startTime):
            if scheduled.startTime < current_hour:
                scheduled.startTime = current_hour
                scheduled.endTime = scheduled.startTime + (scheduled.task.durationMinutes // 60)

            current_hour = scheduled.endTime
            resolved.append(scheduled)

        self.schedule = resolved
        return resolved

    def generateSchedule(self, dayHours: int) -> List[ScheduledTask]:
        """Generate a full day's schedule given the number of available hours."""
        self.schedule = []
        filtered_tasks = self.filterByTimeAvailable()

        current_hour = 0
        max_hours = min(dayHours, self.owner.availableHours)

        for task in filtered_tasks:
            if task.isCompleted:
                continue

            duration_hours = max(1, task.durationMinutes // 60)

            if current_hour + duration_hours <= max_hours:
                scheduled = ScheduledTask(
                    task=task,
                    pet=task.appliesTo[0] if task.appliesTo else self.pets[0] if self.pets else Pet("Unknown", "Unknown", 0),
                    startTime=current_hour,
                    endTime=current_hour + duration_hours,
                    reasoning=f"Scheduled based on {task.priority} priority"
                )
                self.schedule.append(scheduled)
                current_hour += duration_hours

        self.handleConflicts()
        return self.schedule

    def detectConflicts(self) -> List[str]:
        """Return warning messages for any tasks whose time windows overlap.

        Two tasks conflict when their [start, start+duration) intervals intersect.
        Same-pet overlaps are flagged as pet conflicts; different-pet overlaps are
        flagged as owner-time conflicts (the owner can only do one thing at a time).
        Returns an empty list when no conflicts exist — never raises.
        """
        from itertools import combinations

        def _parse(task: Task):
            h, m = task.startTime.split(":")
            start = int(h) * 60 + int(m)
            return start, start + task.durationMinutes

        def fmt(minutes: int) -> str:
            return f"{minutes // 60:02d}:{minutes % 60:02d}"

        parsed = [(task, *_parse(task)) for task in self.tasks]
        warnings: List[str] = []

        for (a, start_a, end_a), (b, start_b, end_b) in combinations(parsed, 2):

            if start_a < end_b and start_b < end_a:
                shared = {p.name for p in a.appliesTo} & {p.name for p in b.appliesTo}
                kind = f"same pet — {', '.join(sorted(shared))}" if shared else "owner time"
                warnings.append(
                    f"[CONFLICT — {kind}] '{a.title}' and '{b.title}' "
                    f"overlap ({a.startTime}-{fmt(end_a)} vs {b.startTime}-{fmt(end_b)})"
                )

        return warnings

    def explainSchedule(self) -> str:
        """Return a human-readable explanation of the generated schedule.

        Times shown are the task's real clock window (startTime + duration), not
        the scheduler's internal hour-block indices, so this matches the schedule
        table the user sees.
        """
        if not self.schedule:
            return f"No tasks scheduled for {self.owner.name}."

        def clock_window(task: Task) -> str:
            """Build a real HH:MM-HH:MM window from the task's start time + duration."""
            hour, minute = (int(x) for x in task.startTime.split(":"))
            start = hour * 60 + minute
            end = start + task.durationMinutes
            return f"{start // 60:02d}:{start % 60:02d} - {end // 60:02d}:{end % 60:02d}"

        explanation = f"Daily schedule for {self.owner.name} ({self.owner.availableHours} hours available):\n\n"

        for scheduled in sorted(self.schedule, key=lambda s: s.task.startTime):
            priority_label = {1: "High", 2: "Medium", 3: "Low"}.get(scheduled.task.priority, "Unknown")
            explanation += f"⏰ {clock_window(scheduled.task)}: {scheduled.task.title} ({scheduled.pet.name})\n"
            explanation += f"   Duration: {scheduled.task.durationMinutes} minutes | Priority: {priority_label}\n"
            explanation += f"   Reason: {scheduled.reasoning}\n\n"

        return explanation